('lib/content/pa_scolarite/mineurs_famille_pages/mise_en_peril/provocation_directe_mineur_crime_delit_contenu_page.dart','f00018','II — Élément matériel',18,'TextSpan','ces comportements peuvent présenter l’infraction sous un jour favorable sans inciter directement à la commettre.','ces comportements peuvent présenter l’infraction sous un jour favorable sans inciter directement à la commettre.','{}'::jsonb,true),
('lib/content/pa_scolarite/mineurs_famille_pages/mise_en_peril/provocation_directe_mineur_crime_delit_contenu_page.dart','f00019','II — Élément matériel',19,'_Paragraph','Il importe peu que la provocation ait été suivie d’effet : l’infraction peut être constituée même si le mineur ne passe pas à l’acte.','Il importe peu que la provocation ait été suivie d’effet : l’infraction peut être constituée même si le mineur ne passe pas à l’acte.','{}'::jsonb,true),
